// 归档保留原next_review推导的复评截面，不以今日钟替后来的申请或答复倒填旧计划。
#include "political_office_resignation_response_validation.hpp"
namespace hanmo::resident {
Status validate_political_office_resignation_response_director(const DirectorCatalog& catalog,const DirectorState& state,const PoliticalOfficeResignationContext* x){
 const auto* responses=catalog.office_resignation_responses.get();if(bool(responses)!=bool(x)||(x&&(x->responses!=responses||x->state.version!=2)))return common_failure("OfficeResignationResponseVersionPairRequired");const auto& policies=catalog.dynamic_subjects?catalog.policies:catalog.subjects;
 for(const auto& row:policies.rows()){const auto& p=row.second;const bool enabled=std::find(p.templates.begin(),p.templates.end(),DirectorTemplate::office_resignation_response)!=p.templates.end();if(enabled!=p.office_resignation_response_intent_id.has_value())return common_failure("OfficeResignationResponseDirectorPolicyMismatch",row.first);if(enabled){const auto* intent=responses?responses->intents.find(*p.office_resignation_response_intent_id):nullptr;if(!intent||row.first!=intent->director_policy_id)return common_failure("OfficeResignationResponseDirectorPolicyMismatch",row.first);}}
 if(x){auto valid=validate_political_office_resignation_responses(*responses,x->common_catalog,x->organization_catalog,x->successions,x->catalog);if(!valid.ok)return valid;for(const auto& row:responses->intents.rows()){const auto& i=row.second;const auto* selected=policies.find(i.director_policy_id);const auto* p=x->catalog.policies.find(i.resignation_policy_id);const auto* head=p?x->successions.policies.find(p->approval_succession_policy_id):nullptr;if(!selected||!head||selected->organization_id!=head->organization_id||selected->office_resignation_response_intent_id!=std::optional<StableId>{i.id}||std::find(selected->templates.begin(),selected->templates.end(),DirectorTemplate::office_resignation_response)==selected->templates.end()||(!catalog.dynamic_subjects&&i.approver_actor_id!=i.director_policy_id))return common_failure("OfficeResignationResponseDirectorPolicyMismatch",i.id);}}
 const auto plans=[&](const OrderedTable<FinitePlan>& table,bool archived)->Status{for(const auto& row:table.rows()){const auto& p=row.second;if(p.template_id!=political_office_resignation_response_template)continue;const auto policy_id=catalog.dynamic_subjects?p.policy_id:p.subject.id;const auto* policy=policies.find(policy_id);const auto* intent=policy&&policy->office_resignation_response_intent_id&&responses?responses->intents.find(*policy->office_resignation_response_intent_id):nullptr;
  if(!x||!intent||p.subject.kind!=SubjectKind::actor||p.subject.id!=intent->approver_actor_id||policy_id!=intent->director_policy_id||!p.commitment_ids.empty()||p.livelihood||p.pending_life_action_id||p.last_life_fact_id||(p.phase!=PlanPhase::waiting&&p.phase!=PlanPhase::delivering&&p.phase!=PlanPhase::accepting&&p.phase!=PlanPhase::completed))return common_failure("OfficeResignationResponsePlanMismatch",row.first);
  const Integer delay=std::max(catalog.retry_delay_ticks,catalog.review_interval_ticks);if(delay<1||p.next_review_tick<delay)return common_failure("OfficeResignationResponseReviewRequired",row.first);const Integer observed=p.next_review_tick-delay;if(observed>x->common.tick())return common_failure("OfficeResignationResponseReviewRequired",row.first);if(!archived){const auto* schedule=state.schedules.find(p.subject.id);if(!schedule||schedule->last_decision_tick!=observed||schedule->next_tick!=p.next_review_tick)return common_failure("OfficeResignationResponseReviewRequired",row.first);}
  const PoliticalOfficeResignationRequest* request=nullptr;if(p.phase==PlanPhase::completed){const auto* a=x->state.answers.find(p.goal_ref);if(!a||a->tick>observed||a->actor_id!=p.subject.id||p.current_action_id)return common_failure("OfficeResignationResponseCompletedSourceRequired",row.first);request=x->state.requests.find(a->request_fact_id);}else {request=x->state.requests.find(p.goal_ref);if(p.phase==PlanPhase::accepting){const PoliticalOfficeResignationAnswer* answer=nullptr;for(const auto& a:x->state.answers.rows())if(a.second.request_fact_id==p.goal_ref)answer=&a.second;const auto* origin=answer?x->state.authored_origins.find(answer->id):nullptr;if(!answer||!origin||origin->intent_id!=intent->id||answer->actor_id!=p.subject.id||answer->tick>observed||p.current_action_id)return common_failure("OfficeResignationResponseAcceptedSourceRequired",row.first);}}
  if(!request||request->approver_actor_id!=p.subject.id||request->policy_id!=intent->resignation_policy_id||request->tick>observed)return common_failure("OfficeResignationResponseKnownRequestRequired",row.first);
 }return common_success();};auto valid=plans(state.plans,false);return valid.ok?plans(state.archived_plans,true):valid;
}
}
